}

function Gone() {
  return (
    <>
      <meta name="robots" content="noindex" />
      <h1>This page has been removed</h1>
      <p><Link to="/">Go to the home page</Link>.</p>
    </>
  );
}

export const router = createBrowserRouter([
  { Component: Layout, children: [
    { index: true, Component: Home },
    { path: 'about', Component: About },
    { path: '410', Component: Gone },     // prerendered, becomes /410.html (drop if nothing is retired)
    { path: '404', Component: NotFound }, // prerendered, becomes /404.html
    { path: '*', Component: NotFound },   // client-side only: the host already answered 404 for this URL
