// Post-build step (before csp-hashes.mjs): node scripts/make-error-pages.mjs dist
// Prerendered /404 (and optional /410) routes become root 404.html / 410.html; the host serves 404.html with status 404
// for URLs with no file, and the 410 edge function returns 410.html with status 410.
import { existsSync, renameSync, rmSync } from 'node:fs';
import { join, resolve } from 'node:path';

const OUT = resolve(process.argv[2] || 'dist');
for (const [code, required] of [['404', true], ['410', false]]) {
  const from = join(OUT, code, 'index.html');
  if (!existsSync(from)) {
    if (required) { console.error(`no prerendered /${code} route: add "/${code}" to the prerender routes`); process.exit(1); }
    continue;
  }
  renameSync(from, join(OUT, `${code}.html`));
  rmSync(join(OUT, code), { recursive: true, force: true }); // /404/ itself must not stay a live 200 page
}
