import { useEffect, useState } from 'react';

type State<T> = { status: 'loading' } | { status: 'error' } | { status: 'ok'; data: T };

// A failed API call (500/503 from the API service, network, timeout) must show an error state, never an empty page that looks like success.
export function useApi<T>(url: string): State<T> {
  const [state, setState] = useState<State<T>>({ status: 'loading' });
  useEffect(() => {
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), 8000);
    fetch(url, { signal: ctl.signal })
      .then((res) => { if (!res.ok) throw new Error(String(res.status)); return res.json() as Promise<T>; })
      .then((data) => setState({ status: 'ok', data }))
      .catch(() => setState({ status: 'error' }))
      .finally(() => clearTimeout(timer));
    return () => ctl.abort();
  }, [url]);
  return state;
}
