// Runs only on the paths listed in _routes.json; context.next() serves everything else from static assets.
const RETIRED = [/^\/old-product\/?$/, /^\/old-section\//];
export async function onRequest(context) {
  const url = new URL(context.request.url);
  if (!RETIRED.some((re) => re.test(url.pathname))) return context.next();
  const page = await context.env.ASSETS.fetch(new URL('/410', url)); // pretty path of 410.html
  const headers = new Headers(page.headers);
  headers.delete('content-encoding');
  headers.delete('content-length');
  headers.set('x-robots-tag', 'noindex');
  return new Response(page.body, { status: 410, headers });
}

A Vite SPA has no server of its own, so this recipe is the CLIENT part only (React 19 shown; Vue and Svelte keep the same fetch logic). The endpoint (serverless function or the project's API; the placeholder is https://example.com/api/contact) MUST implement: same-origin check on `Origin` (fallback `Sec-Fetch-Site`), 403 for cross-site; per-client rate limit answering 429 after N submissions; discard a submission whose honeypot field `website` is filled while answering the same success response; server-side validation and length limits; delivery to the real destination (email provider API, FORM_WEBHOOK_URL or database insert) with an ~8s timeout, answering 502/503 when delivery fails and 2xx only after it succeeded; Turnstile verification is the alternative to the honeypot. For a cross-origin endpoint, build with CSP_CONNECT_EXTRA="https://example.com" (headers recipe) and enable CORS for your site's origin on the endpoint; a same-origin /api/contact needs neither. Success text appears only after `res.ok`.
