import { useState, type FormEvent } from 'react';

const ENDPOINT = 'https://example.com/api/contact';

export function ContactForm() {
  const [status, setStatus] = useState<'idle' | 'sending' | 'sent' | 'rate' | 'error'>('idle');

  async function onSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = e.currentTarget;
    setStatus('sending');
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), 10000);
    try {
      const res = await fetch(ENDPOINT, { method: 'POST', body: new FormData(form), headers: { Accept: 'application/json' }, credentials: 'omit', signal: ctl.signal });
      if (res.status === 429) { setStatus('rate'); return; }
      if (!res.ok) throw new Error(`HTTP ${res.status}`); // never show success on a 4xx/5xx (RES-008)
      form.reset();
      setStatus('sent');
    } catch {
      setStatus('error');
    } finally {
      clearTimeout(timer);
    }
  }

  return (
    <form onSubmit={onSubmit}>
      <p><label htmlFor="name">Name</label>
        <input id="name" name="name" type="text" autoComplete="name" required maxLength={100} /></p>
      <p><label htmlFor="email">Email</label>
        <input id="email" name="email" type="email" autoComplete="email" required maxLength={254} /></p>
      <p><label htmlFor="message">Message</label>
        <textarea id="message" name="message" required maxLength={5000} rows={6} /></p>
      {/* honeypot: hidden by the .hp CSS class (not type=hidden); bots fill it, people never see it */}
      <div className="hp" aria-hidden="true"><label>Leave this empty <input name="website" type="text" tabIndex={-1} autoComplete="off" /></label></div>
      <p><button type="submit" disabled={status === 'sending'}>Send message</button>{' '}
        <a href="/privacy">Privacy notice</a></p>
      <p role="status" aria-live="polite">
        {status === 'sending' && 'Sending...'}
        {status === 'sent' && 'Thank you, we will reply soon.'}
        {status === 'rate' && 'Too many attempts. Please try again later.'}
        {status === 'error' && 'Sorry, your message was not sent. Please try again or email us.'}
      </p>
    </form>
  );
}
