// Post-build step: node scripts/seo-files.mjs dist   (run after csp-hashes.mjs; Node 18+, no dependencies)
// DEPLOY_ENV and SITE_URL are read from the BUILD environment (process.env). Do not use import.meta.env here:
// Vite inlines env into the bundle at build time, and this file is not part of the bundle.
import { existsSync, readdirSync, readFileSync, unlinkSync, writeFileSync, appendFileSync } from 'node:fs';
import { join, relative, resolve } from 'node:path';

const OUT = resolve(process.argv[2] || 'dist');
const production = process.env.DEPLOY_ENV === 'production'; // the one value that means production (IDX-005)
const SITE = (process.env.SITE_URL || 'https://example.com').replace(/\/+$/, '');
const PRIVATE = ['/api/', '/app/']; // app/API paths only - never /assets/, CSS or JS
const headersFile = join(OUT, '_headers');
const hasNoindexHeader = () => existsSync(headersFile) && /x-robots-tag/i.test(readFileSync(headersFile, 'utf8'));

if (!production) {
  writeFileSync(join(OUT, 'robots.txt'), 'User-agent: *\nDisallow: /\n'); // no Sitemap line
  if (existsSync(join(OUT, 'sitemap.xml'))) unlinkSync(join(OUT, 'sitemap.xml')); // missing file = 404 (needs 404.html)
  if (!hasNoindexHeader()) appendFileSync(headersFile, '/*\n  X-Robots-Tag: noindex, nofollow\n'); // csp-hashes.mjs normally wrote it
  console.log('seo-files: non-production -> Disallow: /, no sitemap, X-Robots-Tag noindex');
  process.exit(0);
}
if (!process.env.SITE_URL || /localhost|127\.0\.0\.1|\.local\b/.test(SITE)) { console.error('SITE_URL must be the public https origin'); process.exit(1); }
if (hasNoindexHeader()) { console.error('_headers still sends X-Robots-Tag on a production build'); process.exit(1); }

const walk = (d) => readdirSync(d, { withFileTypes: true }).flatMap((e) =>
  e.isDirectory() ? walk(join(d, e.name)) : e.name.endsWith('.html') ? [join(d, e.name)] : []);
const urls = new Set();
for (const f of walk(OUT)) {
  const rel = '/' + relative(OUT, f).replace(/\\/g, '/');
  if (/^\/(404|410|50x)(\.html|\/index\.html)$/.test(rel) || PRIVATE.some((p) => rel.startsWith(p))) continue; // error pages and app shells are not indexable
  const html = readFileSync(f, 'utf8');
  if (/<meta[^>]+name=["']robots["'][^>]*noindex/i.test(html)) continue;
  const canon = /<link[^>]+rel=["']canonical["'][^>]*href=["']([^"']+)["']/i.exec(html);
  // loc must equal the page's canonical (same scheme/host/trailing-slash policy); fall back to the directory-index form
  urls.add(canon ? canon[1] : SITE + rel.replace(/index\.html$/, '').replace(/\.html$/, ''));
}
for (const u of urls) if (!u.startsWith(SITE + '/')) { console.error(`canonical ${u} is not under ${SITE}`); process.exit(1); }
if (urls.size > 50000) { console.error('over 50,000 URLs: split into a sitemap index'); process.exit(1); }
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');
writeFileSync(join(OUT, 'sitemap.xml'), '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
  [...urls].sort().map((u) => `  <url><loc>${esc(u)}</loc></url>`).join('\n') + '\n</urlset>\n');
writeFileSync(join(OUT, 'robots.txt'), ['User-agent: *', 'Allow: /', ...PRIVATE.map((p) => `Disallow: ${p}`), '', `Sitemap: ${SITE}/sitemap.xml`, ''].join('\n'));
console.log(`seo-files: production -> ${urls.size} URL(s) in sitemap.xml`);
### file: dist/robots.txt
# generated. production:  User-agent: * / Allow: / / Disallow: /api/ / Disallow: /app/ / (blank) / Sitemap: https://example.com/sitemap.xml
# any other DEPLOY_ENV:   User-agent: * / Disallow: /   - no Sitemap line, no sitemap.xml (404 via 404.html), X-Robots-Tag: noindex, nofollow on every response
